"""Original TB chapter: microbiological diagnosis and interpretation."""
from qbank_authoring import question,ref,finalize
WD=ref('WHO Consolidated TB Guidelines, Module 3: Diagnosis, 2025','https://www.who.int/publications/i/item/9789240107984')
WT=ref('WHO Consolidated TB Guidelines, Module 4: Treatment and Care, 2025','https://www.who.int/publications/i/item/9789240107243')
AD=ref('ATS/IDSA/CDC: Diagnosis of Tuberculosis in Adults and Children','https://www.idsociety.org/practice-guideline/diagnosis-of-tb-in-adults-and-children/')
CD=ref('CDC: Clinical and Laboratory TB Diagnosis','https://www.cdc.gov/tb/hcp/testing-diagnosis/clinical-and-laboratory-diagnosis.html')
IG=ref('CDC: Interferon Gamma Release Assay Guidance','https://www.cdc.gov/tb/hcp/testing-diagnosis/interferon-gamma-release-assay.html')
NG=ref('India NTEP: National Guidelines for Management of DR-TB, 2025','https://tbcindia.mohfw.gov.in/wp-content/uploads/2025/01/National-Guidelines-for-Management-of-DR-TB_Final.pdf')
rows=[]
def q(*a,**k):rows.append(question(*a,**k))
q('A sputum smear contains acid-fast bacilli. Which statement is correct?', 'The smear does not by itself distinguish M. tuberculosis complex from nontuberculous mycobacteria',[
 ('Any AFB-positive sputum definitively identifies M. tuberculosis','Species identification requires appropriate additional testing.'),('An AFB-positive smear establishes rifampicin susceptibility','Smear microscopy does not measure susceptibility.'),('AFB positivity proves latent rather than active infection','Organism detection in a compatible respiratory illness raises concern for active disease.')],
 'Acid-fast staining identifies a biological group rather than a complete diagnosis', '**Rapid molecular testing can distinguish TB complex and assess selected resistance markers.**',['Culture remains important for organism recovery and susceptibility assessment.','Use airborne precautions when infectious pulmonary TB is suspected.'], '**Interpret the microbiology with the syndrome.**',['NTM detection also requires assessment before diagnosing NTM disease.','Do not select a full treatment regimen from the smear alone.'],[['Smear','Acid-fast organisms'],['NAAT','TB-complex and selected resistance information'],['Culture/DST','Organism recovery and susceptibility']],[AD,CD])
q('A patient with strong clinical and radiological suspicion of pulmonary TB has negative sputum smears. What is the best next principle?', 'Continue evaluation with molecular testing, cultures and further sampling as indicated',[
 ('Exclude TB because every active case is smear positive','Paucibacillary disease can be smear negative.'),('Use a negative IGRA as a definitive replacement rule-out','Immune tests cannot exclude all active TB.'),('Diagnose drug susceptibility from smear negativity','Bacillary burden and susceptibility are different issues.')],
 'A negative smear has limited exclusion value', '**Smear sensitivity falls with low organism burden.**',['HIV and extrapulmonary disease can complicate diagnosis.','A negative NAAT also cannot exclude all high-probability smear-negative disease.'], '**Obtain an adequate specimen through the appropriate pathway.**',['Induced sputum or bronchoscopy can be considered when needed.','Do not delay treatment of a severe high-probability illness solely for culture confirmation.'],[['Negative smear','Does not exclude TB'],['Molecular test','Rapid additional evidence'],['Persistent suspicion','Culture and further sampling']],[AD],style='clinical_scenario')
q('For an adult with HIV and TB symptoms under WHO 2025 guidance, which initial testing strategy improves detection?', 'Concurrent respiratory low-complexity automated NAAT and urine LF-LAM in the recommended HIV diagnostic pathway',[
 ('Sputum smear alone as the preferred complete investigation','It misses some paucibacillary and disseminated disease.'),('IGRA alone to diagnose active TB','It measures infection-related immune response rather than proving active disease.'),('Urine dipstick protein as a substitute for LF-LAM','These are unrelated assays.')],
 'Concurrent specimen testing can address low respiratory organism burden', '**WHO 2025 recommends concurrent testing in the specified symptomatic or high-risk HIV population.**',['LF-LAM detects a mycobacterial antigen in urine.','Respiratory molecular testing contributes TB and resistance evidence.'], '**Use both tests within the clinical pathway.**',['A negative result does not erase a high-probability diagnosis.','Obtain additional site-specific specimens when disseminated disease is suspected.'],[['Respiratory sample','Automated NAAT'],['Urine','LF-LAM'],['Purpose','Improve initial TB detection in HIV']],[WD])
q('A lymph-node biopsy is planned for suspected TB. What specimen-handling principle is essential?', 'Reserve suitable unfixed tissue for microbiological culture and molecular testing as well as tissue for histology',[
 ('Place every fragment in formalin before arranging culture','Fixation compromises viable-organism recovery.'),('Use only an overlying skin swab','It does not adequately sample the node.'),('Omit microbiology whenever granulomas are expected','Histology alone may not identify the organism or resistance.')],
 'Tissue should answer both pathological and microbiological questions', '**Extrapulmonary TB can be paucibacillary.**',['A negative stain does not exclude it.','Culture and validated NAAT can provide additional confirmation.'], '**Coordinate collection with pathology and microbiology.**',['Document the suspected site and differential.','Preserve material for susceptibility work when organism recovery is possible.'],[['Histology','Tissue reaction and differential'],['Unfixed specimen','Culture and indicated molecular tests'],['Planning','Allocate material before fixation']],[AD,CD],style='clinical_scenario')
q('Why is mycobacterial culture still valuable after a positive rapid TB molecular test?', 'It recovers viable organisms and supports additional susceptibility assessment',[
 ('It is always faster than molecular detection','Conventional growth-based results generally take longer.'),('It eliminates the need to interpret every clinical finding','Microbiology still requires clinical integration.'),('A positive molecular test already proves susceptibility to all TB drugs','Most rapid assays assess only selected targets.')],
 'Rapid detection and comprehensive characterization are complementary', '**Molecular assays accelerate initial diagnosis and selected resistance detection.**',['Culture can enable phenotypic testing and broader investigation.','Prior therapy and specimen quality influence yield.'], '**Do not postpone urgent treatment while waiting for growth.**',['Adapt the regimen when reliable susceptibility information arrives.','Interpret molecular/phenotypic discordance with expert laboratory input.'],[['NAAT','Rapid targeted evidence'],['Culture','Viable isolate'],['DST','More complete regimen guidance']],[WD,AD])
q('A BCG-vaccinated adult needs testing for TB infection. Which test is less affected by prior BCG vaccination?', 'An interferon-gamma release assay',[
 ('A conventional tuberculin skin test','BCG can contribute to skin-test reactivity.'),('A chest radiograph as a direct measure of immune sensitization','Imaging assesses disease features rather than immune sensitization.'),('Sputum smear as the routine latent-infection test','Smear is used to evaluate organisms, not latent immune sensitization.')],
 'Selected antigen specificity helps avoid BCG-related cross-reactivity', '**IGRAs use antigens absent from BCG strains.**',['They still have limitations with immunosuppression and early infection.','A positive result does not itself establish active disease.'], '**Select the test according to age, setting and guideline.**',['Interpret it within exposure and progression risk.','Exclude active disease before preventive treatment when indicated.'],[['BCG effect','Can influence TST'],['IGRA','Not affected by BCG vaccination'],['Positive result','Requires disease assessment']],[IG])
q('A close contact is tested two weeks after the last infectious TB exposure and has a negative IGRA. What is the best interpretation?', 'The immune-conversion window may not have elapsed; repeat testing at the recommended post-exposure interval is needed',[
 ('Recent exposure can be excluded permanently','Early immune testing can be negative.'),('Start a full active-TB regimen solely because exposure occurred','Exposure alone is not a disease diagnosis.'),('BCG status makes repeat exposure assessment unnecessary','Vaccination does not eliminate infection risk.')],
 'Immune tests depend on time after infection', '**A recent negative result can precede measurable sensitization.**',['Contact investigations commonly repeat testing about 8–10 weeks after last exposure.','Young children and immunocompromised contacts may need additional preventive measures.'], '**Assess symptoms and high-risk circumstances immediately.**',['Do not wait for repeat immune testing to investigate possible active disease.','Coordinate follow-up through the contact-investigation pathway.'],[['Early test','Can be falsely negative'],['Repeat','Usually 8–10 weeks after last exposure'],['Symptoms','Immediate disease evaluation']],[IG],style='clinical_scenario')
q('A rapid molecular TB assay reports rifampicin resistance. What is the most appropriate response?', 'Enter the drug-resistant TB pathway and obtain further relevant susceptibility information promptly',[
 ('Assume susceptibility to every other drug without testing','Additional resistance must be assessed.'),('Ignore the result until the standard regimen fails for months','This delays effective treatment.'),('Add a single drug to a failing regimen without a complete plan','This can amplify resistance.')],
 'A rapid resistance marker changes the initial treatment pathway', '**Rifampicin resistance is a major regimen-defining result.**',['Fluoroquinolone and other key-drug susceptibility can affect shorter-regimen eligibility.','Unexpected discordant findings need expert laboratory assessment.'], '**Use a complete effective regimen through the programmatic pathway.**',['Review prior drug exposure and contact resistance history.','Adjust when reliable additional results arrive.'],[['Rapid result','Rifampicin resistance'],['Next','Expanded relevant DST'],['Treatment','Complete DR-TB regimen']],[WD,NG])
q('A patient previously treated for TB has a positive sputum NAAT during evaluation of new symptoms. Which limitation matters?', 'Molecular detection can persist from nonviable organisms, so relapse assessment needs clinical, culture and resistance context',[
 ('Every positive post-treatment NAAT proves viable relapse','Residual DNA can complicate interpretation.'),('A positive result proves no treatment was taken','It cannot establish adherence history.'),('Molecular tests are a universal substitute for culture-based response monitoring','They do not reliably determine viable-organism clearance.')],
 'Nucleic-acid persistence differs from viable-organism persistence', '**Prior TB treatment changes the interpretation of a positive molecular result.**',['Assess the interval, symptoms and imaging.','Culture and susceptibility testing can help evaluate recurrent disease.'], '**Do not dismiss genuine recurrence either.**',['Reinfection and relapse are both possible.','Choose treatment from the full assessment and resistance risk.'],[['NAAT','Target nucleic acid'],['Culture','Viability evidence'],['Recurrent symptoms','Integrated relapse/reinfection evaluation']],[WD,CD],style='clinical_scenario')
q('A biopsy from a patient with prolonged fever shows necrotizing granulomatous inflammation. Which conclusion is strongest?', 'TB is an important possibility, but microbiological evaluation and the broader differential remain necessary',[
 ('Histology alone proves drug-susceptible M. tuberculosis','It does not identify susceptibility and is not completely specific.'),('All granulomas are sarcoidosis','Infectious and other causes must be considered.'),('A negative acid-fast stain excludes TB in the tissue','Paucibacillary tissue can be stain negative.')],
 'A tissue-reaction pattern narrows but does not finish the diagnosis', '**Mycobacteria and fungi can produce granulomatous inflammation.**',['Noninfectious conditions can also enter the differential.','Exposure, immune status and site guide additional tests.'], '**Pursue direct organism evidence where feasible.**',['Use appropriate fresh tissue for culture and validated molecular testing.','Integrate pathology with imaging and clinical probability.'],[['Histology','Suggestive pattern'],['Microbiology','Etiological evidence'],['Susceptibility','Requires appropriate resistance testing']],[AD],style='clinical_scenario')

if __name__=='__main__':print('TB diagnosis: '+str(len(rows))+' questions drafted')
